CREATE TABLE business_settings(business_id INTEGER PRIMARY KEY REFERENCES businesses(id),year_start_month INTEGER NOT NULL DEFAULT 4 CHECK(year_start_month BETWEEN 1 AND 12));
CREATE TABLE product_groups(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL REFERENCES businesses(id),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 160),UNIQUE(business_id,id),UNIQUE(business_id,name));
CREATE TABLE product_variants(business_id INTEGER NOT NULL,product_id INTEGER NOT NULL,group_id INTEGER NOT NULL,attributes TEXT NOT NULL CHECK(json_valid(attributes)),PRIMARY KEY(business_id,product_id),UNIQUE(business_id,group_id,attributes),FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id),FOREIGN KEY(business_id,group_id) REFERENCES product_groups(business_id,id));
